import logging
import pytest
from unittest.mock import MagicMock, patch
from async_telemetry_gateway.app.utils import log_and_metric_exception, get_breaker_state_value

class TestTelemetryUtils:
    """
    Suite for validating telemetry utility functions and Prometheus metric integrations.
    """

    @pytest.mark.parametrize("state, expected_value", [
        ("closed", 0),
        ("open", 1),
        ("half-open", 2),
        ("unknown", -1),
        ("", -1),
        (None, -1),
    ])
    def test_get_breaker_state_value(self, state, expected_value):
        """
        Validates the mapping of circuit breaker string states to integer values.
        Ensures robust handling of unexpected input strings.
        """
        assert get_breaker_state_value(state) == expected_value

    def test_log_and_metric_exception_success(self):
        """
        Validates that log_and_metric_exception correctly logs an error 
        and increments the associated Prometheus counter.
        """
        # Mocking components
        mock_logger = MagicMock(spec=logging.Logger)
        mock_counter = MagicMock()
        
        test_exception = ValueError("Simulated system failure")
        test_message = "Failed to process telemetry packet"
        
        # Execution
        log_and_metric_exception(
            logger_obj=mock_logger,
            metric_counter=mock_counter,
            exception=test_exception,
            message=test_message
        )

        # Assertions
        # Verify logger was called with the correct message and exception info
        mock_logger.error.assert_called_once()
        args, kwargs = mock_logger.error.call_args
        assert test_message in args[0]
        assert test_exception in args[0]
        assert kwargs.get("exc_info") is True

        # Verify counter was incremented exactly once
        mock_counter.inc.assert_called_once()

    def test_log_and_metric_exception_with_extra_kwargs(self):
        """
        Ensures that additional keyword arguments are passed correctly to the logger.
        """
        mock_logger = MagicMock(spec=logging.Logger)
        mock_counter = MagicMock()
        
        log_and_metric_exception(
            logger_obj=mock_logger,
            metric_counter=mock_counter,
            exception=Exception("Error"),
            message="Msg",
            extra_context="data"
        )

        # Verify that 'extra_context' reached the logger call
        _, kwargs = mock_logger.error.call_args
        assert kwargs.get("extra_context") == "data"
        mock_counter.inc.assert_called_once()

